INSERT INTO destinations (id, slug, name, region, state, country, latitude, longitude, summary, description,
    hero_image_url, hero_image_credit, best_time_to_visit, recommended_days_min, recommended_days_max,
    budget_per_day_min, budget_per_day_max, currency, how_to_reach, local_transport, travel_tips, safety_info, faqs,
    status, featured, seo_title, seo_description, is_seed_data, popularity, created_at, updated_at) VALUES
('d0000000-0000-4000-8000-000000000001', 'gokarna', 'Gokarna', 'Uttara Kannada', 'Karnataka', 'India', 14.547900, 74.318800,
 'A temple town with a string of quiet cliff-backed beaches linked by a coastal trail.',
 'Gokarna is a pilgrimage town on the Karnataka coast, centred on the Mahabaleshwar Temple. South of town, Kudle, Om, Half Moon and Paradise beaches sit in separate coves joined by a rocky coastal path, which makes the area popular for beach-hopping treks. It is quieter and more rustic than Goa, with simple guesthouses and beach shacks.',
 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Delight_india.jpg/1280px-Delight_india.jpg', 'Wikimedia Commons',
 'October to March, when the sea is calmer and days are dry. Monsoon (June to September) brings heavy rain and rough seas.',
 2, 3, 1500.00, 4000.00, 'INR',
 'From Bangalore: about 480 km by road (8 to 9 hours). Overnight buses run to Gokarna. By train, Gokarna Road station on the Konkan Railway is about 10 km from town. Nearest airports are Goa (Dabolim) and Hubballi.',
 'Auto-rickshaws connect the town to Kudle and Om beaches. Half Moon and Paradise beaches are reached on foot by the coastal trail or by boat from Om Beach. Scooter rentals are common in town.',
 'Start the beach trek early to avoid midday heat|Carry water and cash; card acceptance is patchy at beaches|Dress modestly when visiting the temple|Boats back from Paradise Beach are easier to find in the afternoon',
 'Swim only at beaches where locals and lifeguards indicate it is safe; currents can be strong, especially at Om and Paradise beaches. The trail between coves is rocky and slippery after rain.',
 '[{"question":"Is Gokarna good for a weekend trip from Bangalore?","answer":"It is possible with an overnight bus or train each way, but two full days on the ground is more comfortable."},{"question":"Can I swim at the beaches?","answer":"Some beaches are calm in season, but currents vary. Follow local advice and avoid swimming in monsoon."}]',
 'PUBLISHED', TRUE, 'Gokarna travel guide: beaches, temple and the coastal trek', 'Plan a Gokarna trip: Om, Kudle, Half Moon and Paradise beaches, the Mahabaleshwar Temple, how to reach from Bangalore and budget estimates.', TRUE, 95, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000002', 'coorg', 'Coorg', 'Kodagu', 'Karnataka', 'India', 12.424400, 75.738200,
 'Misty coffee country in the Western Ghats with waterfalls, viewpoints and forest treks.',
 'Coorg (Kodagu) is a hilly district known for coffee and spice estates, homestays and a distinct Kodava culture. Madikeri is the main town and a good base for Abbey Falls and Raja''s Seat. Further out are the Tibetan settlement at Bylakuppe, the source of the Kaveri at Talacauvery and longer treks such as Tadiandamol.',
 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Tadiandamol_Valley%2C_Western_Ghats.jpg/1280px-Tadiandamol_Valley%2C_Western_Ghats.jpg', 'Wikimedia Commons',
 'October to March for pleasant weather. Waterfalls are fullest just after the monsoon (August to October).',
 2, 4, 2500.00, 6000.00, 'INR',
 'From Bangalore: about 250 km by road via Mysuru (5 to 6 hours). KSRTC buses run to Madikeri. The nearest railway station is Mysuru (about 120 km); the nearest airports are Mangaluru and Mysuru.',
 'Local buses link the main towns, but sights are spread out. Hiring a taxi for the day or driving your own vehicle is the practical option. Jeeps are used for the rough road to Mandalpatti.',
 'Book homestays early for long weekends|Carry a light jacket even in summer evenings|Leeches are common on forest trails in monsoon; wear long socks|Buy coffee and spices directly from estates',
 'Mountain roads are narrow with sharp bends; avoid driving after dark if unfamiliar. Some trekking routes need forest department permission and a guide.',
 '[{"question":"How many days do I need in Coorg?","answer":"Two days covers Madikeri, Abbey Falls and Raja''s Seat; three or four days allows Bylakuppe, Talacauvery or a trek."},{"question":"Is Coorg good for families?","answer":"Yes. Most viewpoints, the elephant camp and the monastery are easy to visit with children and older parents."}]',
 'PUBLISHED', TRUE, 'Coorg travel guide: coffee estates, waterfalls and viewpoints', 'Plan a Coorg (Kodagu) trip: Abbey Falls, Raja''s Seat, Dubare, Bylakuppe, treks, how to reach from Bangalore and budget estimates.', TRUE, 90, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000003', 'hampi', 'Hampi', 'Vijayanagara', 'Karnataka', 'India', 15.335000, 76.460000,
 'Ruins of the Vijayanagara capital spread across a surreal boulder landscape on the Tungabhadra.',
 'Hampi is a UNESCO World Heritage Site with temples, palaces and market streets from the Vijayanagara Empire, set among granite boulder hills and banana plantations. The Virupaksha Temple is still in worship, while the Vittala Temple complex with its stone chariot is the best-known monument. Sunrise and sunset from the hills are a highlight.',
 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Wide_angle_of_Galigopuram_of_Virupaksha_Temple%2C_Hampi_%2804%29_%28cropped%29.jpg/1280px-Wide_angle_of_Galigopuram_of_Virupaksha_Temple%2C_Hampi_%2804%29_%28cropped%29.jpg', 'Wikimedia Commons',
 'October to February. Summer (March to May) is very hot; plan sightseeing for early morning and late afternoon.',
 2, 3, 1200.00, 3500.00, 'INR',
 'From Bangalore: about 340 km by road (6 to 7 hours). Overnight trains and buses run to Hosapete, about 13 km from Hampi. The nearest airport is at Vidyanagar (Ballari district) with limited flights; Hubballi is another option.',
 'Bicycles, scooters and auto-rickshaws are the usual way around. The core monuments are spread over several kilometres, so plan a route by area: Hampi Bazaar, the Vittala area and the Royal Centre.',
 'Start early; the rocks heat up quickly|One ASI ticket usually covers several monuments in a day; keep it with you|Hire a licensed guide for the history|Carry water and sun protection',
 'Climbing boulders is risky without experience. Watch for monkeys around food. Coracle rides depend on river levels and may stop in high water.',
 '[{"question":"Is two days enough for Hampi?","answer":"Two full days covers the main monuments by bicycle or auto-rickshaw. Add a day for a slower pace or the area across the river."},{"question":"Do I need a guide?","answer":"Not required, but a licensed guide helps explain the history and the layout of the ruins."}]',
 'PUBLISHED', TRUE, 'Hampi travel guide: Vijayanagara ruins, temples and sunsets', 'Plan a Hampi trip: Virupaksha and Vittala temples, Royal Centre, Hemakuta and Matanga hills, how to reach from Bangalore and budget estimates.', TRUE, 88, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000004', 'chikmagalur', 'Chikmagalur', 'Chikkamagaluru', 'Karnataka', 'India', 13.315300, 75.775400,
 'The birthplace of Indian coffee, with the highest peak in Karnataka and estate stays.',
 'Chikmagalur is a hill district of coffee estates and shola forests in the Western Ghats. Mullayanagiri, the highest peak in Karnataka, and the Baba Budangiri range are short drives from town. It suits slow estate stays, drives through plantations and moderate treks.',
 'https://upload.wikimedia.org/wikipedia/commons/d/db/Chikmagalur%2C_India._%287793316622%29.jpg', 'Wikimedia Commons',
 'September to March. Monsoon (June to August) is lush but very wet, and some peak roads close in heavy rain.',
 2, 3, 2500.00, 6000.00, 'INR',
 'From Bangalore: about 245 km by road (about 5 hours). Regular KSRTC buses run to Chikmagalur town. The nearest railheads are Kadur and Birur (about 40 km); the nearest airport is Mangaluru.',
 'A private vehicle or hired taxi is the practical way to reach the peaks and estates. Jeeps are used for the rough track to the waterfalls near Baba Budangiri.',
 'Reach Mullayanagiri early for clear views|Weekend traffic on the peak road can be heavy|Estate stays often include plantation walks|Carry rain gear outside winter',
 'Peak roads are narrow with hairpin bends and sudden fog. Trekking in protected areas needs forest department permits.',
 '[{"question":"What is Chikmagalur known for?","answer":"Coffee estates, Mullayanagiri peak, the Baba Budangiri range and quiet homestays."},{"question":"Can I visit in a weekend?","answer":"Yes. Leave Bangalore early on the first day and you can cover the peaks and an estate visit in two days."}]',
 'PUBLISHED', FALSE, 'Chikmagalur travel guide: coffee estates and Mullayanagiri peak', 'Plan a Chikmagalur trip: Mullayanagiri, Baba Budangiri, estate stays, treks, how to reach from Bangalore and budget estimates.', TRUE, 80, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000005', 'murudeshwar', 'Murudeshwar', 'Uttara Kannada', 'Karnataka', 'India', 14.094000, 74.484300,
 'A seaside temple town with a towering Shiva statue and scuba diving at Netrani Island.',
 'Murudeshwar sits on a small headland on the Arabian Sea, crowned by a large Shiva statue and a tall temple gopura. The beach is lively in the evenings. It is also the jumping-off point for scuba diving and snorkelling trips to Netrani Island in season.',
 'https://upload.wikimedia.org/wikipedia/commons/d/dc/Shiva_Statue_Murdeshwara_Temple.jpg', 'Wikimedia Commons',
 'October to May. Dive trips to Netrani usually run in this window and stop in the monsoon.',
 1, 2, 1500.00, 4000.00, 'INR',
 'From Bangalore: about 490 km by road (9 to 10 hours). Murdeshwar station on the Konkan Railway is close to town, and overnight buses run from Bangalore. Mangaluru is the nearest major airport.',
 'The temple, statue and beach are within walking distance. Dive operators arrange boats to Netrani Island.',
 'Book scuba trips in advance and confirm what the price includes|Visit the gopura viewpoint in the morning for clearer views|Dress modestly at the temple',
 'Only dive with certified operators who provide a safety briefing and equipment checks. Avoid swimming where flags or lifeguards advise against it.',
 '[{"question":"Can beginners scuba dive at Netrani?","answer":"Many operators offer introductory dives for non-certified divers with an instructor. Check health requirements before booking."},{"question":"How long should I stay?","answer":"One day covers the temple and beach; add a day for a Netrani dive trip."}]',
 'PUBLISHED', FALSE, 'Murudeshwar travel guide: Shiva statue, beach and Netrani diving', 'Plan a Murudeshwar trip: the temple and Shiva statue, beach evenings, scuba at Netrani Island, how to reach and budget estimates.', TRUE, 70, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000006', 'udupi', 'Udupi', 'Udupi', 'Karnataka', 'India', 13.340900, 74.742100,
 'A coastal temple town famous for its Krishna Matha, beaches and vegetarian cuisine.',
 'Udupi is known for the Sri Krishna Matha and for giving its name to a style of South Indian vegetarian food. Malpe Beach is a short drive away, and boats from Malpe go to St. Mary''s Island with its hexagonal basalt columns. The university town of Manipal is next door.',
 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Udupi_Krishna_Temple.jpg/1280px-Udupi_Krishna_Temple.jpg', 'Wikimedia Commons',
 'October to March. Ferries to St. Mary''s Island generally do not run during the monsoon.',
 1, 2, 1500.00, 3500.00, 'INR',
 'From Bangalore: about 400 km by road (7 to 8 hours). Udupi station is on the Konkan Railway, and overnight buses are frequent. Mangaluru airport is about 60 km away.',
 'City buses and auto-rickshaws cover Udupi, Malpe and Manipal. Hire a taxi for Kaup Beach and longer trips.',
 'Try a traditional meal on banana leaf near the temple|Check ferry timings to St. Mary''s Island on the day|Kaup lighthouse is best near sunset',
 'Swimming is restricted at some beaches; follow lifeguard instructions. St. Mary''s Island has no shade, so carry water and sun protection.',
 '[{"question":"Is Udupi good for vegetarians?","answer":"Yes. Udupi is known for vegetarian cooking, and many restaurants near the temple serve traditional meals."},{"question":"Can I combine Udupi with other places?","answer":"It pairs well with Murudeshwar and Gokarna further north on the same coast."}]',
 'PUBLISHED', FALSE, 'Udupi travel guide: Krishna Matha, Malpe and St. Mary''s Island', 'Plan an Udupi trip: Sri Krishna Matha, Malpe Beach, St. Mary''s Island, Kaup lighthouse, food, how to reach and budget estimates.', TRUE, 68, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000007', 'karwar', 'Karwar', 'Uttara Kannada', 'Karnataka', 'India', 14.813600, 74.129400,
 'A quiet port town where the Kali river meets the sea, with islands and uncrowded beaches.',
 'Karwar is a relaxed coastal town at the mouth of the Kali river, close to the Goa border. It has a long town beach, a decommissioned warship museum, and boat trips to nearby islands such as Kurumgad. Devbagh, across the river mouth, offers a quieter beach stay.',
 'https://upload.wikimedia.org/wikipedia/commons/2/29/Karwar_Evening.jpg', 'Wikimedia Commons',
 'October to March for calm seas. Boat trips are usually suspended in the monsoon.',
 2, 3, 1800.00, 4500.00, 'INR',
 'From Bangalore: about 520 km by road (9 to 10 hours). Karwar station is on the Konkan Railway, and overnight buses run from Bangalore. Goa (Dabolim) airport is roughly 100 km away.',
 'Auto-rickshaws work in town. Island visits are by boat from the jetty or through resorts; hire a taxi for Devbagh and Sadashivgad.',
 'Combine Karwar with Gokarna or south Goa|Arrange island boats only with licensed operators|Sunset over the Kali bridge is worth timing',
 'Parts of the coast are near naval areas with restricted access; follow signage. Wear life jackets on all boat trips.',
 '[{"question":"Is Karwar crowded?","answer":"It is generally much quieter than Goa, especially on weekdays."},{"question":"How do I reach the islands?","answer":"By boat from Karwar or through resorts at Devbagh, in season and weather permitting."}]',
 'PUBLISHED', FALSE, 'Karwar travel guide: quiet beaches, islands and the Kali river', 'Plan a Karwar trip: Tagore Beach, the warship museum, Devbagh, Kurumgad Island, Sadashivgad, how to reach and budget estimates.', TRUE, 55, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000008', 'jog-falls', 'Jog Falls', 'Shivamogga', 'Karnataka', 'India', 14.229400, 74.812400,
 'One of the highest plunge waterfalls in India, at its most dramatic just after the monsoon.',
 'At Jog Falls the Sharavathi river drops over a cliff in four separate streams. Flow is controlled by the Linganamakki Dam upstream, so the falls are strongest during and just after the monsoon and can be thin in summer. Viewpoints are close to the parking area, and a long flight of steps leads towards the base when open.',
 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Jog_Falls_05092016.jpg/1280px-Jog_Falls_05092016.jpg', 'Wikimedia Commons',
 'August to November, when the falls carry the most water. Mist can hide the view at the peak of the monsoon.',
 1, 2, 1500.00, 3500.00, 'INR',
 'From Bangalore: about 380 km by road (about 7 hours) via Shivamogga and Sagar. The nearest railhead is Talaguppa (about 16 km). Buses run from Sagar and Shivamogga.',
 'A private vehicle or taxi is the easiest way to combine the falls with Linganamakki Dam and nearby temples.',
 'Check recent photos or local news for water levels before going|The steps to the base are steep; go in the morning|Combine with Sagar and Keladi for a day of heritage',
 'Stay behind railings at viewpoints. Access to the base is sometimes closed for safety in high water. Paths are slippery in the rain.',
 '[{"question":"When is the best time to see Jog Falls?","answer":"Shortly after the monsoon, roughly August to November, when water flow is high and mist is lower."},{"question":"Is Jog Falls a day trip from Bangalore?","answer":"It is a long drive each way; an overnight stay near Sagar or Jog makes the trip more comfortable."}]',
 'PUBLISHED', FALSE, 'Jog Falls travel guide: best season, viewpoints and nearby places', 'Plan a Jog Falls trip: viewpoints, the steps to the base, Linganamakki Dam, best season, how to reach from Bangalore and budget estimates.', TRUE, 62, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000009', 'dandeli', 'Dandeli', 'Uttara Kannada', 'Karnataka', 'India', 15.249000, 74.617000,
 'River adventures and jungle stays on the Kali, inside a protected forest landscape.',
 'Dandeli sits on the Kali river surrounded by the Dandeli Wildlife Sanctuary, part of the Kali Tiger Reserve. It is best known for white-water rafting, kayaking and jungle lodges. Hornbills and other forest birds are commonly seen, while larger animals are harder to spot.',
 'https://upload.wikimedia.org/wikipedia/commons/5/53/Dandeli_1.jpg', 'Wikimedia Commons',
 'October to May. Rafting generally runs in this window, with river flow depending on dam releases.',
 2, 3, 2500.00, 6000.00, 'INR',
 'From Bangalore: about 470 km by road (8 to 9 hours). Hubballi, about 75 km away, has an airport and a major railway station; Alnavar is the nearest railhead.',
 'Most visitors stay at resorts or jungle lodges that arrange transfers and activities. Local taxis are available from Dandeli town.',
 'Book rafting slots in advance on weekends|Carry insect repellent and quick-dry clothing|Keep noise low on safaris to improve sightings',
 'Rafting requires life jackets and a briefing; follow the guides. Do not enter the river outside supervised activities, as currents change with dam releases.',
 '[{"question":"Is rafting in Dandeli safe for beginners?","answer":"Operators run graded stretches with guides and safety gear. Age and health limits apply; check with the operator."},{"question":"Will I see tigers?","answer":"Tiger sightings are rare. Birds, deer and other wildlife are more commonly seen."}]',
 'PUBLISHED', FALSE, 'Dandeli travel guide: rafting, jungle stays and wildlife', 'Plan a Dandeli trip: Kali river rafting, kayaking, wildlife safaris, Syntheri Rocks, how to reach from Bangalore and budget estimates.', TRUE, 66, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('d0000000-0000-4000-8000-000000000010', 'goa', 'Goa', 'North and South Goa', 'Goa', 'India', 15.490900, 73.827800,
 'Beaches, Portuguese heritage, forts and nightlife across India''s smallest state.',
 'Goa combines lively northern beaches such as Baga and Anjuna with calmer southern bays like Palolem. Old Goa has UNESCO-listed churches including the Basilica of Bom Jesus, and Panaji''s Fontainhas quarter keeps its colourful Portuguese-era streets. Inland, Dudhsagar Falls sits on the Karnataka border in the Western Ghats.',
 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/BeachFun.jpg/1280px-BeachFun.jpg', 'Wikimedia Commons',
 'November to February for dry, pleasant weather. Monsoon (June to September) is green and quiet, with rough seas.',
 3, 5, 2500.00, 8000.00, 'INR',
 'From Bangalore: about 560 km by road (10 to 11 hours). Frequent flights reach Goa (Dabolim) and Mopa airports. Trains run to Madgaon and Vasco da Gama, and many overnight buses run to Panaji and Mapusa.',
 'Scooter and car rentals are the most common way to get around. App and local taxis are available; buses connect the main towns.',
 'Stay in the north for nightlife and the south for quieter beaches|Carry a valid licence for scooter rental|Dudhsagar access changes by season; check before planning|Book stays early around Christmas and New Year',
 'Swim only in flagged zones with lifeguards. Do not drink and drive; checks are common. Keep valuables secure at busy beaches.',
 '[{"question":"North or South Goa?","answer":"North Goa is busier with nightlife and markets. South Goa is quieter, with calmer beaches."},{"question":"How many days do I need?","answer":"Three days covers the highlights of one region; five days lets you see both north and south at an easy pace."}]',
 'PUBLISHED', TRUE, 'Goa travel guide: beaches, heritage, forts and Dudhsagar', 'Plan a Goa trip: Baga, Palolem, Fort Aguada, Old Goa churches, Fontainhas, Dudhsagar Falls, how to reach from Bangalore and budget estimates.', TRUE, 99, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

