-- ───────────── Attractions ─────────────
-- Columns: id, destination_id, slug, name, category, description, latitude, longitude,
--          typical_duration_minutes, cost_min, cost_max, cost_note, best_time_of_day,
--          opening_hours_note, tags, family_friendly, accessibility_note
INSERT INTO attractions (id, destination_id, slug, name, category, description, latitude, longitude,
    typical_duration_minutes, cost_min, cost_max, currency, cost_note, best_time_of_day, opening_hours_note,
    opening_hours_verified, tags, family_friendly, accessibility_note, is_seed_data, created_at, updated_at) VALUES
-- Gokarna
('a0000000-0000-4000-8000-000000001001', 'd0000000-0000-4000-8000-000000000001', 'om-beach', 'Om Beach', 'BEACH', 'Twin curved bays said to resemble the Om symbol, with shacks and seasonal water sports.', 14.519600, 74.322600, 150, 0, 800, 'INR', 'Beach is free; water sports and food extra (estimate)', 'AFTERNOON', NULL, FALSE, 'beach,water-sports,sunset', TRUE, 'Steps and sand; not wheelchair friendly', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000001002', 'd0000000-0000-4000-8000-000000000001', 'kudle-beach', 'Kudle Beach', 'BEACH', 'A long, relaxed beach with cafes and guesthouses, popular for sunsets.', 14.532300, 74.315000, 120, 0, 500, 'INR', 'Free; cafe spend extra (estimate)', 'EVENING', NULL, FALSE, 'beach,sunset,cafes', TRUE, 'Reached by steps or a steep path', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000001003', 'd0000000-0000-4000-8000-000000000001', 'half-moon-beach', 'Half Moon Beach', 'BEACH', 'A small secluded cove reached on foot over the headland from Om Beach, or by boat.', 14.511200, 74.323200, 120, 0, 300, 'INR', 'Free on foot; boat ride extra (estimate)', 'MORNING', NULL, FALSE, 'beach,trek,secluded', FALSE, 'Rocky trail access only', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000001004', 'd0000000-0000-4000-8000-000000000001', 'paradise-beach', 'Paradise Beach', 'BEACH', 'The last and most remote cove on the trail, with rocks and clear water.', 14.504100, 74.325900, 150, 0, 500, 'INR', 'Free on foot; boat back extra (estimate)', 'MORNING', NULL, FALSE, 'beach,trek,secluded,adventure', FALSE, 'Rocky trail access only', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000001005', 'd0000000-0000-4000-8000-000000000001', 'gokarna-beach-trek', 'Gokarna Beach Trek', 'ADVENTURE', 'A coastal walk linking Kudle, Om, Half Moon and Paradise beaches over rocky headlands.', 14.518000, 74.322000, 300, 0, 1500, 'INR', 'Free; optional boat return extra (estimate)', 'MORNING', NULL, FALSE, 'trek,adventure,beach,photography', FALSE, 'Uneven terrain; moderate fitness needed', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000001006', 'd0000000-0000-4000-8000-000000000001', 'mahabaleshwar-temple', 'Mahabaleshwar Temple', 'TEMPLE', 'An important Shiva temple at the heart of Gokarna town.', 14.543400, 74.316800, 60, 0, 100, 'INR', 'Entry free; offerings optional', 'MORNING', 'Dress code applies; timings not verified', FALSE, 'temple,culture,heritage', TRUE, 'Crowded on festival days', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000001007', 'd0000000-0000-4000-8000-000000000001', 'gokarna-main-beach', 'Gokarna Main Beach', 'BEACH', 'The town beach beside the temple streets, busy with pilgrims in the evening.', 14.546800, 74.314700, 60, 0, 0, 'INR', 'Free', 'EVENING', NULL, FALSE, 'beach,sunset,culture', TRUE, 'Flat access from town', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000001008', 'd0000000-0000-4000-8000-000000000001', 'mirjan-fort', 'Mirjan Fort', 'FORT', 'A laterite fort with moats and ramparts on the Aghanashini river, about 20 km from Gokarna.', 14.491600, 74.419800, 90, 0, 50, 'INR', 'Small entry fee (estimate)', 'AFTERNOON', NULL, FALSE, 'fort,history,photography', TRUE, 'Uneven stone paths', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000001009', 'd0000000-0000-4000-8000-000000000001', 'yana-rocks', 'Yana Rocks', 'NATURE', 'Two massive karst rock outcrops in the forest, reached by a short walk; about 50 km from Gokarna.', 14.589000, 74.565000, 240, 0, 200, 'INR', 'Small parking or entry fee (estimate)', 'MORNING', NULL, FALSE, 'nature,trek,adventure,photography', TRUE, 'Forest path with steps', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
-- Coorg
('a0000000-0000-4000-8000-000000002001', 'd0000000-0000-4000-8000-000000000002', 'abbey-falls', 'Abbey Falls', 'WATERFALL', 'A waterfall set among coffee and spice estates near Madikeri, reached by a short path with steps.', 12.457200, 75.717500, 90, 15, 50, 'INR', 'Entry and parking fee (estimate)', 'MORNING', NULL, FALSE, 'waterfall,nature,photography', TRUE, 'Many steps down to the viewing bridge', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000002002', 'd0000000-0000-4000-8000-000000000002', 'rajas-seat', 'Raja''s Seat', 'VIEWPOINT', 'A garden viewpoint in Madikeri overlooking valleys and ridges, known for sunsets.', 12.419400, 75.736400, 60, 5, 20, 'INR', 'Small entry fee (estimate)', 'EVENING', NULL, FALSE, 'viewpoint,sunset,family', TRUE, 'Paved garden paths', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000002003', 'd0000000-0000-4000-8000-000000000002', 'madikeri-fort', 'Madikeri Fort', 'FORT', 'A 19th-century fort in the town centre with a small museum and old church.', 12.421000, 75.739300, 45, 0, 20, 'INR', 'Free or nominal (estimate)', 'ANY', NULL, FALSE, 'fort,history,heritage', TRUE, 'Mostly level ground', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000002004', 'd0000000-0000-4000-8000-000000000002', 'dubare-elephant-camp', 'Dubare Elephant Camp', 'WILDLIFE', 'A forest department elephant camp on the Kaveri, reached by a short boat crossing.', 12.368700, 75.904600, 150, 50, 1500, 'INR', 'Boat and activity fees vary widely (estimate)', 'MORNING', 'Activity windows are short and in the morning; not verified', FALSE, 'wildlife,family,river', TRUE, 'Boat crossing required', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000002005', 'd0000000-0000-4000-8000-000000000002', 'namdroling-monastery', 'Namdroling Monastery', 'TEMPLE', 'The Golden Temple at Bylakuppe, a large Tibetan Buddhist monastery and settlement.', 12.430500, 76.097500, 90, 0, 0, 'INR', 'Free', 'AFTERNOON', NULL, FALSE, 'culture,monastery,family', TRUE, 'Level access to the main hall', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000002006', 'd0000000-0000-4000-8000-000000000002', 'talacauvery', 'Talacauvery', 'TEMPLE', 'The traditional source of the Kaveri river, with a temple and hilltop views on the Brahmagiri range.', 12.385800, 75.493000, 120, 0, 50, 'INR', 'Free; parking extra (estimate)', 'MORNING', NULL, FALSE, 'temple,viewpoint,culture', TRUE, 'Steep steps to the hilltop', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000002007', 'd0000000-0000-4000-8000-000000000002', 'mandalpatti', 'Mandalpatti Viewpoint', 'VIEWPOINT', 'Grassland ridge above the clouds, reached by jeep on a rough track.', 12.540000, 75.660000, 180, 300, 1500, 'INR', 'Jeep hire shared per group (estimate)', 'MORNING', NULL, FALSE, 'viewpoint,adventure,photography', TRUE, 'Bumpy jeep ride', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000002008', 'd0000000-0000-4000-8000-000000000002', 'tadiandamol-trek', 'Tadiandamol Trek', 'ADVENTURE', 'A full-morning trek to the highest peak in Kodagu through shola forest and grassland.', 12.217000, 75.637000, 360, 0, 500, 'INR', 'Forest entry or guide fee may apply (estimate)', 'MORNING', 'Permits and timings set by forest department; not verified', FALSE, 'trek,adventure,mountains', FALSE, 'Strenuous; good fitness needed', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
-- Hampi
('a0000000-0000-4000-8000-000000003001', 'd0000000-0000-4000-8000-000000000003', 'virupaksha-temple', 'Virupaksha Temple', 'TEMPLE', 'A living temple with a towering gateway at the end of Hampi Bazaar.', 15.335000, 76.459400, 75, 0, 50, 'INR', 'Entry free; camera fee may apply (estimate)', 'MORNING', NULL, FALSE, 'temple,heritage,culture', TRUE, 'Remove footwear; stone floors', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000003002', 'd0000000-0000-4000-8000-000000000003', 'vittala-temple', 'Vittala Temple and Stone Chariot', 'HERITAGE', 'The most celebrated complex in Hampi, with the stone chariot and ornate mandapas.', 15.342300, 76.474700, 120, 40, 600, 'INR', 'ASI ticket; Indian and foreign visitor rates differ (estimate)', 'MORNING', NULL, FALSE, 'heritage,history,photography', TRUE, 'Battery vehicles run from the parking area', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000003003', 'd0000000-0000-4000-8000-000000000003', 'hemakuta-hill', 'Hemakuta Hill', 'VIEWPOINT', 'A low rocky hill dotted with early temples, a short walk from the bazaar. Popular at sunset.', 15.334300, 76.458000, 60, 0, 0, 'INR', 'Free', 'EVENING', NULL, FALSE, 'viewpoint,sunset,heritage', TRUE, 'Sloping rock surface', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000003004', 'd0000000-0000-4000-8000-000000000003', 'matanga-hill', 'Matanga Hill', 'VIEWPOINT', 'The highest point in central Hampi with a panoramic view; a steep climb best done for sunrise.', 15.337500, 76.465500, 120, 0, 0, 'INR', 'Free', 'MORNING', NULL, FALSE, 'viewpoint,sunrise,adventure,trek', FALSE, 'Steep rock steps', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000003005', 'd0000000-0000-4000-8000-000000000003', 'lotus-mahal', 'Lotus Mahal and Zenana Enclosure', 'HERITAGE', 'An elegant Indo-Islamic pavilion inside the walled royal women''s quarters.', 15.319700, 76.471700, 75, 40, 600, 'INR', 'ASI ticket, often combined with other monuments (estimate)', 'AFTERNOON', NULL, FALSE, 'heritage,history,photography', TRUE, 'Mostly level', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000003006', 'd0000000-0000-4000-8000-000000000003', 'elephant-stables', 'Elephant Stables', 'HERITAGE', 'A long row of domed chambers built for the royal elephants.', 15.320700, 76.474000, 40, 0, 0, 'INR', 'Usually covered by the same ticket as Lotus Mahal (estimate)', 'AFTERNOON', NULL, FALSE, 'heritage,history', TRUE, 'Level lawns', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000003007', 'd0000000-0000-4000-8000-000000000003', 'hampi-bazaar', 'Hampi Bazaar', 'MARKET', 'The ancient market street in front of Virupaksha Temple, lined with pavilions and small shops.', 15.335400, 76.461000, 45, 0, 0, 'INR', 'Free to walk; shopping extra', 'ANY', NULL, FALSE, 'market,heritage,shopping', TRUE, 'Level street', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000003008', 'd0000000-0000-4000-8000-000000000003', 'tungabhadra-coracle-ride', 'Coracle Ride on the Tungabhadra', 'ADVENTURE', 'A short ride in a traditional round basket boat among the river boulders.', 15.340500, 76.472000, 45, 100, 300, 'INR', 'Per person, depends on group and season (estimate)', 'MORNING', 'Runs only when river levels allow; not verified', FALSE, 'river,adventure,family', TRUE, 'Boarding from rocks', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
-- Chikmagalur
('a0000000-0000-4000-8000-000000004001', 'd0000000-0000-4000-8000-000000000004', 'mullayanagiri', 'Mullayanagiri Peak', 'VIEWPOINT', 'The highest peak in Karnataka, with a short final climb on steps to a small temple at the top.', 13.390600, 75.721400, 180, 0, 100, 'INR', 'Parking or entry fee may apply (estimate)', 'MORNING', 'Access may be regulated on weekends; not verified', FALSE, 'viewpoint,mountains,trek,sunrise', TRUE, 'About 500 steps to the summit', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000004002', 'd0000000-0000-4000-8000-000000000004', 'baba-budangiri', 'Baba Budangiri', 'HERITAGE', 'A hill range and shrine linked to the legend of coffee arriving in India.', 13.430000, 75.752000, 120, 0, 0, 'INR', 'Free', 'MORNING', NULL, FALSE, 'heritage,mountains,culture', TRUE, 'Hill road and steps', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000004003', 'd0000000-0000-4000-8000-000000000004', 'jhari-falls', 'Jhari Falls', 'WATERFALL', 'A cascade in the coffee estates below Baba Budangiri, reached by jeep and a short walk.', 13.411000, 75.740000, 150, 500, 1000, 'INR', 'Jeep hire shared per group (estimate)', 'MORNING', NULL, FALSE, 'waterfall,adventure,nature', TRUE, 'Rough jeep track', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000004004', 'd0000000-0000-4000-8000-000000000004', 'kemmangundi', 'Kemmangundi', 'VIEWPOINT', 'A hill station with gardens and viewpoints, a scenic drive from Chikmagalur town.', 13.550000, 75.750000, 180, 0, 100, 'INR', 'Garden entry fee may apply (estimate)', 'AFTERNOON', NULL, FALSE, 'viewpoint,family,mountains', TRUE, 'Garden paths', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000004005', 'd0000000-0000-4000-8000-000000000004', 'hirekolale-lake', 'Hirekolale Lake', 'NATURE', 'A quiet reservoir backed by hills, good for a calm sunset stop.', 13.333000, 75.713000, 60, 0, 0, 'INR', 'Free', 'EVENING', NULL, FALSE, 'nature,sunset,romantic,photography', TRUE, 'Roadside access', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000004006', 'd0000000-0000-4000-8000-000000000004', 'kudremukh-trek', 'Kudremukh Trek', 'ADVENTURE', 'A long guided trek across grassland ridges in Kudremukh National Park.', 13.200000, 75.250000, 420, 500, 1500, 'INR', 'Forest permit and guide fees (estimate)', 'MORNING', 'Permits required from the forest department; not verified', FALSE, 'trek,adventure,mountains,nature', FALSE, 'Strenuous full-day hike', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000004007', 'd0000000-0000-4000-8000-000000000004', 'belavadi-temple', 'Veeranarayana Temple, Belavadi', 'TEMPLE', 'A Hoysala-era temple with fine stone carving, a short drive from Chikmagalur.', 13.250000, 75.940000, 60, 0, 0, 'INR', 'Free', 'AFTERNOON', NULL, FALSE, 'temple,heritage,history', TRUE, 'Level courtyard', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
-- Murudeshwar
('a0000000-0000-4000-8000-000000005001', 'd0000000-0000-4000-8000-000000000005', 'murudeshwar-temple', 'Murudeshwar Temple and Raja Gopura', 'TEMPLE', 'Seaside Shiva temple with a very tall gopura; a lift goes up for views of the coast.', 14.094300, 74.484800, 90, 0, 50, 'INR', 'Entry free; lift ticket small (estimate)', 'MORNING', 'Dress code applies; timings not verified', FALSE, 'temple,viewpoint,culture', TRUE, 'Lift available to the viewing level', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000005002', 'd0000000-0000-4000-8000-000000000005', 'murudeshwar-shiva-statue', 'Shiva Statue', 'VIEWPOINT', 'A giant seated Shiva statue on the headland, overlooking the sea.', 14.093700, 74.485700, 45, 0, 0, 'INR', 'Free', 'ANY', NULL, FALSE, 'viewpoint,photography,culture', TRUE, 'Ramps and steps', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000005003', 'd0000000-0000-4000-8000-000000000005', 'murudeshwar-beach', 'Murudeshwar Beach', 'BEACH', 'A busy beach beside the temple, with snacks and boat rides in the evening.', 14.095500, 74.486800, 120, 0, 500, 'INR', 'Free; boat rides extra (estimate)', 'EVENING', NULL, FALSE, 'beach,sunset,family', TRUE, 'Flat sand', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0000000-0000-4000-8000-000000005004', 'd0000000-0000-4000-8000-000000000005', 'netrani-island-scuba', 'Netrani Island Scuba Diving', 'ADVENTURE', 'Boat trip to a small offshore island for introductory dives and snorkelling over coral reefs.', 14.016700, 74.333300, 360, 4000, 8000, 'INR', 'Depends on operator and dive type (estimate)', 'MORNING', 'Seasonal; operators decide daily based on sea conditions', FALSE, 'scuba,snorkeling,adventure,island', FALSE, 'Requires swimming confidence and health declaration', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
-- Udupi
('a0000000-0000-4000-8000-000000006001', 'd0000000-0000-4000-8000-000000000006', 'sri-krishna-matha', 'Sri Krishna Matha', 'TEMPLE', 'A famous Krishna temple and monastery complex at the heart of Udupi.', 13.341500, 74.751600, 90, 0, 0, 'INR', 'Free', 'MORNING', 'Dress code applies; timings not verified', FALSE, 'temple,culture,food', TRUE, 'Crowded at festival times', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
